contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller (as address) cannot be changed here because msg.sender is this contract
    // so we model two scenarios by taking owner param and recipient and an amount to fund c
    function run(address ownerAddr, address payable recipient, uint256 fund) public payable {
        require(ownerAddr != address(0) && recipient != address(0));
        // fund the test contract so it can send Ether to c if requested
        if (fund > 0) {
            require(address(this).balance >= fund);
            // send Ether to c via fallback to set its balance
            (bool sent, ) = address(c).call{value: fund}("\x00");
            // ignore send outcome; if it fails then c balance unchanged
            sent; 
        }

        // deployer of c was external test harness; here we only interact through c
        // read pre-state: c.owner getter and balances
        address beforeOwner = c.owner();
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        // Attempt withdrawAll as this contract (msg.sender == address(this)).
        // The call will succeed only if c.owner() == address(this)
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        address afterOwner = c.owner();
        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // The general rule:
        // - owner doesn't change due to withdrawAll
        // - if caller is owner (address(this) == beforeOwner) then withdraw succeeds (not reverted),
        //   C's balance becomes zero and recipient receives the funds (so this contract's balance unchanged aside from gas),
        //   otherwise the call reverts and balances unchanged.
        // We cannot account gas exactly; instead we assert that if caller==owner then cBalanceAfter==0 and if caller!=owner then cBalanceAfter==cBalanceBefore.
        assert(
            afterOwner == beforeOwner
            && ((beforeOwner == address(this)) ? (!reverted && cBalanceAfter == 0) : (reverted && cBalanceAfter == cBalanceBefore))
        );
    }

    receive() external payable {}
}

