        uint256 afterRecipient = recipient.balance;

        // General rule: if caller is the owner (ensured above), withdrawAll must not revert
        // and must drain c's entire balance (afterC == 0) and recipient's balance must have increased by beforeC
        assert(!reverted && afterC == 0 && afterRecipient >= beforeRecipientIncrease(beforeC, recipient));
    }

    // helper view to compute expected recipient balance lower bound without reading internal state of c
    function beforeRecipientIncrease(uint256 beforeC, address payable recipient) internal view returns (uint256) {
        // We can't read recipient's previous balance here directly inside the assert, so compute expected minimum
        // Since beforeC is what c held before, recipient's balance must increase by exactly beforeC when transfer succeeds.
        // Return the required new balance value: original_balance + beforeC
        // But original_balance isn't available in pure/internal context; instead we read it here.
        return recipient.balance - 0 + beforeC - 0; // simplifies to recipient.balance + beforeC
    }

    receive() external payable {}
}

