        assert(
            // If caller is owner and call did not revert then c's balance decreased by some amount <= balanceBefore
            ((iAmOwner && !reverted) ? (balanceAfter <= balanceBefore) : true)
            &&
            // If caller is not owner then either reverted or balance unchanged
            ((!iAmOwner) ? (reverted || (balanceAfter == balanceBefore)) : true)
        );
    }

